import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print(0)
        return

    n = int(data[0])
    if n == 0:
        print(0)
        return

    original = []
    for i in range(1, n + 1):
        original.append(data[i].strip())

    reversed_set = set()
    for s in original:
        reversed_set.add(s[::-1])

    count = 0
    for s in original:
        rev = s[::-1]
        if rev in reversed_set:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
